# Code snippets obtained from actual repository source, rendered with line labels.
def find_lines(path,fragment,pad_before=2,pad_after=7):
    arr=(ROOT/path).read_text(encoding='utf8').splitlines()
    for i,line in enumerate(arr):
        if fragment in line:return list(range(max(1,i+1-pad_before),min(len(arr),i+1+pad_after)+1))
    raise ValueError(path+' cannot find '+fragment)

